insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'reproduction-development', 'Spermatogenesis', 'Spermatogenesis is the process by which haploid spermatozoa develop from germ cells in the seminiferous tubules of the testicle. This process starts with the mitotic division of the stem cells located close to the basement membrane of the tubules. These cells are called spermatogonial stem cells. The mitotic division of these produces two types of cells. Type A cells replenish the stem cells, and type B cells differentiate into primary spermatocytes. The primary spermatocyte divides meiotically (Meiosis I) into two secondary spermatocytes; each secondary spermatocyte divides into two equal haploid spermatids by Meiosis II. The spermatids are transformed into spermatozoa (sperm) by the process of spermiogenesis. These develop into mature spermatozoa, also known as sperm cells. Thus, the primary spermatocyte gives rise to two cells, the secondary spermatocytes, and the two secondary spermatocytes by their subdivision produce four spermatozoa and four haploid cells.', 'Wikipedia: Spermatogenesis', 'https://en.wikipedia.org/w/index.php?title=Spermatogenesis&oldid=1378315853', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'reproduction-development' and body = 'Spermatogenesis is the process by which haploid spermatozoa develop from germ cells in the seminiferous tubules of the testicle. This process starts with the mitotic division of the stem cells located close to the basement membrane of the tubules. These cells are called spermatogonial stem cells. The mitotic division of these produces two types of cells. Type A cells replenish the stem cells, and type B cells differentiate into primary spermatocytes. The primary spermatocyte divides meiotically (Meiosis I) into two secondary spermatocytes; each secondary spermatocyte divides into two equal haploid spermatids by Meiosis II. The spermatids are transformed into spermatozoa (sperm) by the process of spermiogenesis. These develop into mature spermatozoa, also known as sperm cells. Thus, the primary spermatocyte gives rise to two cells, the secondary spermatocytes, and the two secondary spermatocytes by their subdivision produce four spermatozoa and four haploid cells.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'reproduction-development', 'Spermatogenesis', 'Spermatozoa are the mature male gametes in many sexually reproducing organisms. Thus, spermatogenesis is the male version of gametogenesis, of which the female equivalent is oogenesis. In mammals it occurs in the seminiferous tubules of the male testes in a stepwise fashion. Spermatogenesis is highly dependent upon optimal conditions for the process to occur correctly, and is essential for sexual reproduction. DNA methylation and histone modification have been implicated in the regulation of this process. It starts during puberty and usually continues uninterrupted until death, although a slight decrease can be discerned in the quantity of produced sperm with increase in age (see Male infertility). Spermatogenesis starts in the bottom part of seminiferous tubes and, progressively, cells go deeper into tubes and moving along it until mature spermatozoa reaches the lumen, where mature spermatozoa are deposited. The division happens asynchronically; if the tube is cut transversally one could observe different maturation states. A group of cells with different maturation states that are being generated at the same time is called a spermatogenic wave.', 'Wikipedia: Spermatogenesis', 'https://en.wikipedia.org/w/index.php?title=Spermatogenesis&oldid=1378315853', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'reproduction-development' and body = 'Spermatozoa are the mature male gametes in many sexually reproducing organisms. Thus, spermatogenesis is the male version of gametogenesis, of which the female equivalent is oogenesis. In mammals it occurs in the seminiferous tubules of the male testes in a stepwise fashion. Spermatogenesis is highly dependent upon optimal conditions for the process to occur correctly, and is essential for sexual reproduction. DNA methylation and histone modification have been implicated in the regulation of this process. It starts during puberty and usually continues uninterrupted until death, although a slight decrease can be discerned in the quantity of produced sperm with increase in age (see Male infertility). Spermatogenesis starts in the bottom part of seminiferous tubes and, progressively, cells go deeper into tubes and moving along it until mature spermatozoa reaches the lumen, where mature spermatozoa are deposited. The division happens asynchronically; if the tube is cut transversally one could observe different maturation states. A group of cells with different maturation states that are being generated at the same time is called a spermatogenic wave.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'reproduction-development', 'Spermatogenesis: Purpose', 'Spermatogenesis produces mature male gametes, commonly called sperm but more specifically known as spermatozoa, which are able to fertilize the counterpart female gamete, the oocyte, during conception to produce a single-celled individual known as a zygote. This is the cornerstone of sexual reproduction and involves the two gametes both contributing half the normal set of chromosomes (haploid) to result in a chromosomally normal (diploid) zygote. To preserve the number of chromosomes in the offspring – which differs between species – one of each gamete must have half the usual number of chromosomes present in other body cells. Otherwise, the offspring will have twice the normal number of chromosomes, and serious abnormalities may result. In humans, chromosomal abnormalities arising from incorrect spermatogenesis results in congenital defects and abnormal birth defects (Down syndrome, Klinefelter syndrome) and in most cases, spontaneous abortion of the developing foetus.', 'Wikipedia: Spermatogenesis', 'https://en.wikipedia.org/w/index.php?title=Spermatogenesis&oldid=1378315853', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'reproduction-development' and body = 'Spermatogenesis produces mature male gametes, commonly called sperm but more specifically known as spermatozoa, which are able to fertilize the counterpart female gamete, the oocyte, during conception to produce a single-celled individual known as a zygote. This is the cornerstone of sexual reproduction and involves the two gametes both contributing half the normal set of chromosomes (haploid) to result in a chromosomally normal (diploid) zygote. To preserve the number of chromosomes in the offspring – which differs between species – one of each gamete must have half the usual number of chromosomes present in other body cells. Otherwise, the offspring will have twice the normal number of chromosomes, and serious abnormalities may result. In humans, chromosomal abnormalities arising from incorrect spermatogenesis results in congenital defects and abnormal birth defects (Down syndrome, Klinefelter syndrome) and in most cases, spontaneous abortion of the developing foetus.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'reproduction-development', 'Spermatogenesis: Location in humans', 'Spermatogenesis takes place within several structures of the male reproductive system. The initial stages occur within the testes and progress to the epididymis where the developing gametes mature and are stored until ejaculation. The seminiferous tubules of the testes are the starting point for the process, where Spermatogonial Stem Cells adjacent to the inner tubule wall divide in a centripetal direction—beginning at the walls and proceeding into the innermost part, or lumen—to produce immature sperm. Maturation occurs in the epididymis. The location [Testes/Scrotum] is important as the process of spermatogenesis requires a lower temperature to produce viable sperm, specifically 1°-8 °C lower than normal body temperature of 37 °C (98.6 °F). Clinically, small fluctuations in temperature, such as from an athletic support strap, cause no impairment in sperm viability or count.', 'Wikipedia: Spermatogenesis', 'https://en.wikipedia.org/w/index.php?title=Spermatogenesis&oldid=1378315853', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'reproduction-development' and body = 'Spermatogenesis takes place within several structures of the male reproductive system. The initial stages occur within the testes and progress to the epididymis where the developing gametes mature and are stored until ejaculation. The seminiferous tubules of the testes are the starting point for the process, where Spermatogonial Stem Cells adjacent to the inner tubule wall divide in a centripetal direction—beginning at the walls and proceeding into the innermost part, or lumen—to produce immature sperm. Maturation occurs in the epididymis. The location [Testes/Scrotum] is important as the process of spermatogenesis requires a lower temperature to produce viable sperm, specifically 1°-8 °C lower than normal body temperature of 37 °C (98.6 °F). Clinically, small fluctuations in temperature, such as from an athletic support strap, cause no impairment in sperm viability or count.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'reproduction-development', 'Spermatogenesis: Duration', 'For humans, the entire process of spermatogenesis is variously estimated as taking between 72 and 74 days (according to tritium-labelled biopsies) and approximately 120 days (according to DNA clock measurements). Including the transport on ductal system, it takes 3 months. Testes produce 200 to 300 million spermatozoa daily. However, only about half or 100 million of these become viable sperm.', 'Wikipedia: Spermatogenesis', 'https://en.wikipedia.org/w/index.php?title=Spermatogenesis&oldid=1378315853', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'reproduction-development' and body = 'For humans, the entire process of spermatogenesis is variously estimated as taking between 72 and 74 days (according to tritium-labelled biopsies) and approximately 120 days (according to DNA clock measurements). Including the transport on ductal system, it takes 3 months. Testes produce 200 to 300 million spermatozoa daily. However, only about half or 100 million of these become viable sperm.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'reproduction-development', 'Spermatogenesis: Stages', 'The entire process of spermatogenesis can be broken up into several distinct stages, each corresponding to a particular type of cell in humans. In the following table, ploidy, copy number and chromosome/chromatid counts are for one cell, generally prior to DNA synthesis and division (in G1 if applicable). The primary spermatocyte is arrested after DNA synthesis and prior to division.', 'Wikipedia: Spermatogenesis', 'https://en.wikipedia.org/w/index.php?title=Spermatogenesis&oldid=1378315853', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'reproduction-development' and body = 'The entire process of spermatogenesis can be broken up into several distinct stages, each corresponding to a particular type of cell in humans. In the following table, ploidy, copy number and chromosome/chromatid counts are for one cell, generally prior to DNA synthesis and division (in G1 if applicable). The primary spermatocyte is arrested after DNA synthesis and prior to division.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'reproduction-development', 'Spermatogenesis: Spermatocytogenesis', 'Spermatocytogenesis is the male form of gametocytogenesis and results in the formation of spermatocytes possessing half the normal complement of genetic material. In spermatocytogenesis, a diploid spermatogonium, which resides in the basal compartment of the seminiferous tubules, divides mitotically, producing two diploid intermediate cells called primary spermatocytes. Each primary spermatocyte then moves into the adluminal compartment of the seminiferous tubules and duplicates its DNA and subsequently undergoes meiosis I to produce two haploid secondary spermatocytes, which will later divide once more into haploid spermatids. This division implicates sources of genetic variation, such as random inclusion of either parental chromosomes, and chromosomal crossover that increases the genetic variability of the gamete. The DNA damage response (DDR) machinery plays an important role in spermatogenesis. The protein FMRP binds to meiotic chromosomes and regulates the dynamics of the DDR machinery during spermatogenesis. FMRP appears to be necessary for the repair of DNA damage. During spermatocytogenesis, meiosis employs special DNA repair processes that remove DNA damages and help maintain the integrity of the genome that is passed on to progeny. These DNA repair processes include homologous recombinational repair and non-homologous end joining', 'Wikipedia: Spermatogenesis', 'https://en.wikipedia.org/w/index.php?title=Spermatogenesis&oldid=1378315853', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'reproduction-development' and body = 'Spermatocytogenesis is the male form of gametocytogenesis and results in the formation of spermatocytes possessing half the normal complement of genetic material. In spermatocytogenesis, a diploid spermatogonium, which resides in the basal compartment of the seminiferous tubules, divides mitotically, producing two diploid intermediate cells called primary spermatocytes. Each primary spermatocyte then moves into the adluminal compartment of the seminiferous tubules and duplicates its DNA and subsequently undergoes meiosis I to produce two haploid secondary spermatocytes, which will later divide once more into haploid spermatids. This division implicates sources of genetic variation, such as random inclusion of either parental chromosomes, and chromosomal crossover that increases the genetic variability of the gamete. The DNA damage response (DDR) machinery plays an important role in spermatogenesis. The protein FMRP binds to meiotic chromosomes and regulates the dynamics of the DDR machinery during spermatogenesis. FMRP appears to be necessary for the repair of DNA damage. During spermatocytogenesis, meiosis employs special DNA repair processes that remove DNA damages and help maintain the integrity of the genome that is passed on to progeny. These DNA repair processes include homologous recombinational repair and non-homologous end joining');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'reproduction-development', 'Spermatogenesis: Spermatocytogenesis', 'Each cell division from a spermatogonium to a spermatid is incomplete; the cells remain connected to one another by bridges of cytoplasm to allow synchronous development. Not all spermatogonia divide to produce spermatocytes; otherwise, the supply of spermatogonia would run out. Instead, spermatogonial stem cells divide mitotically to produce copies of themselves, ensuring a constant supply of spermatogonia to fuel spermatogenesis.', 'Wikipedia: Spermatogenesis', 'https://en.wikipedia.org/w/index.php?title=Spermatogenesis&oldid=1378315853', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'reproduction-development' and body = 'Each cell division from a spermatogonium to a spermatid is incomplete; the cells remain connected to one another by bridges of cytoplasm to allow synchronous development. Not all spermatogonia divide to produce spermatocytes; otherwise, the supply of spermatogonia would run out. Instead, spermatogonial stem cells divide mitotically to produce copies of themselves, ensuring a constant supply of spermatogonia to fuel spermatogenesis.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'reproduction-development', 'Oogenesis', 'Oogenesis () or ovogenesis is female gametogenesis, the development of the egg cell (ovum) from the oogonium to a primary oocyte, and secondary oocyte. The egg cell is a cell that is competent to further develop when fertilized. Oogenesis is initiated during early embryonic development. Oogonia originate from primordial germ cells (PGCs). The primordial germ cells arise from extraembryonic tissue, known as fetal membranes in humans and other mammals. Somatic cells arise from embryonic tissue. In the extraembryonic tissues the primordial germ cells avoid differentiation signals. PGCs migrate to the genital ridges, precursors to the gonads, ovaries in females, where they proliferate by mitosis to produce a large number of oogonia as primary oocytes.', 'Wikipedia: Oogenesis', 'https://en.wikipedia.org/w/index.php?title=Oogenesis&oldid=1381166131', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'reproduction-development' and body = 'Oogenesis () or ovogenesis is female gametogenesis, the development of the egg cell (ovum) from the oogonium to a primary oocyte, and secondary oocyte. The egg cell is a cell that is competent to further develop when fertilized. Oogenesis is initiated during early embryonic development. Oogonia originate from primordial germ cells (PGCs). The primordial germ cells arise from extraembryonic tissue, known as fetal membranes in humans and other mammals. Somatic cells arise from embryonic tissue. In the extraembryonic tissues the primordial germ cells avoid differentiation signals. PGCs migrate to the genital ridges, precursors to the gonads, ovaries in females, where they proliferate by mitosis to produce a large number of oogonia as primary oocytes.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'reproduction-development', 'Oogenesis: Stages', 'Oogenesis progresses through oocytogenesis the formation of the primary oocyte, to the secondary oocyte and finally to ootidogenesis, the final maturation of the egg cell. Folliculogenesis is a separate parallel process that accompanies oocyte development. Oogonium —(Oocytogenesis)—> Primary Oocyte —(Meiosis I)—> First Polar body (Discarded afterward) + Secondary oocyte —(Meiosis II)—> Second Polar Body (Discarded afterward) + Ovum Oocyte meiosis, important to all animal life cycles yet unlike all other instances of animal cell division, occurs completely without the aid of spindle-coordinating centrosomes.', 'Wikipedia: Oogenesis', 'https://en.wikipedia.org/w/index.php?title=Oogenesis&oldid=1381166131', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'reproduction-development' and body = 'Oogenesis progresses through oocytogenesis the formation of the primary oocyte, to the secondary oocyte and finally to ootidogenesis, the final maturation of the egg cell. Folliculogenesis is a separate parallel process that accompanies oocyte development. Oogonium —(Oocytogenesis)—> Primary Oocyte —(Meiosis I)—> First Polar body (Discarded afterward) + Secondary oocyte —(Meiosis II)—> Second Polar Body (Discarded afterward) + Ovum Oocyte meiosis, important to all animal life cycles yet unlike all other instances of animal cell division, occurs completely without the aid of spindle-coordinating centrosomes.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'reproduction-development', 'Oogenesis: Development', 'Oogonia originate from primordial germ cells (PGCs). The primordial germ cells arise from extraembryonic tissue, known as fetal membranes in humans and other mammals. Somatic cells arise from embryonic tissue. In the extraembryonic tissues the primordial germ cells avoid differentiation signals. PGCs migrate to the genital ridges, precursors to the gonads, ovaries in females, where they proliferate by mitosis to produce a large number of oogonia as primary oocytes.', 'Wikipedia: Oogenesis', 'https://en.wikipedia.org/w/index.php?title=Oogenesis&oldid=1381166131', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'reproduction-development' and body = 'Oogonia originate from primordial germ cells (PGCs). The primordial germ cells arise from extraembryonic tissue, known as fetal membranes in humans and other mammals. Somatic cells arise from embryonic tissue. In the extraembryonic tissues the primordial germ cells avoid differentiation signals. PGCs migrate to the genital ridges, precursors to the gonads, ovaries in females, where they proliferate by mitosis to produce a large number of oogonia as primary oocytes.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'reproduction-development', 'Oogenesis: Maintenance of meiotic arrest', 'Mammalian oocytes are maintained in meiotic prophase arrest for a very long time—months in mice, years in humans. Initially, the arrest is due to lack of sufficient cell cycle proteins to allow meiotic progression. However, as the oocyte grows, these proteins are synthesized, and meiotic arrest becomes dependent on cyclic AMP. The cyclic AMP is generated by the oocyte by adenylyl cyclase in the oocyte membrane. The adenylyl cyclase is kept active by a constitutively active G protein-coupled receptor known as GPR3 and a G protein, Gs, also present in the oocyte membrane. Maintenance of meiotic arrest also depends on the presence of a multilayered complex of cells, known as a follicle, that surrounds the oocyte. Removal of the oocyte from the follicle causes meiosis to progress in the oocyte. The cells that comprise the follicle, known as granulosa cells, are connected to each other by proteins known as gap junctions, that allow small molecules to pass between the cells. The granulosa cells produce a small molecule, cyclic GMP, that diffuses into the oocyte through the gap junctions. In the oocyte, cyclic GMP prevents the breakdown of cyclic AMP by the phosphodiesterase PDE3, and thus maintains meiotic arrest. The cyclic GMP is produced by the guanylyl cyclase NPR2.', 'Wikipedia: Oogenesis', 'https://en.wikipedia.org/w/index.php?title=Oogenesis&oldid=1381166131', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'reproduction-development' and body = 'Mammalian oocytes are maintained in meiotic prophase arrest for a very long time—months in mice, years in humans. Initially, the arrest is due to lack of sufficient cell cycle proteins to allow meiotic progression. However, as the oocyte grows, these proteins are synthesized, and meiotic arrest becomes dependent on cyclic AMP. The cyclic AMP is generated by the oocyte by adenylyl cyclase in the oocyte membrane. The adenylyl cyclase is kept active by a constitutively active G protein-coupled receptor known as GPR3 and a G protein, Gs, also present in the oocyte membrane. Maintenance of meiotic arrest also depends on the presence of a multilayered complex of cells, known as a follicle, that surrounds the oocyte. Removal of the oocyte from the follicle causes meiosis to progress in the oocyte. The cells that comprise the follicle, known as granulosa cells, are connected to each other by proteins known as gap junctions, that allow small molecules to pass between the cells. The granulosa cells produce a small molecule, cyclic GMP, that diffuses into the oocyte through the gap junctions. In the oocyte, cyclic GMP prevents the breakdown of cyclic AMP by the phosphodiesterase PDE3, and thus maintains meiotic arrest. The cyclic GMP is produced by the guanylyl cyclase NPR2.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'reproduction-development', 'Oogenesis: Reinitiation of meiosis', 'As follicles grow, they acquire receptors for luteinizing hormone, a pituitary hormone that reinitiates meiosis in the oocyte and causes ovulation of a fertilizable egg. Luteinizing hormone acts on receptors in the outer layers of granulosa cells of the follicle, causing a decrease in cyclic GMP in the granulosa cells. Because the granulosa cells and oocyte are connected by gap junctions, cyclic GMP also decreases in the oocyte, causing meiosis to resume. Meiosis then proceeds to second metaphase, where it pauses again until fertilization. Luteinizing hormone also stimulates gene expression leading to ovulation.', 'Wikipedia: Oogenesis', 'https://en.wikipedia.org/w/index.php?title=Oogenesis&oldid=1381166131', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'reproduction-development' and body = 'As follicles grow, they acquire receptors for luteinizing hormone, a pituitary hormone that reinitiates meiosis in the oocyte and causes ovulation of a fertilizable egg. Luteinizing hormone acts on receptors in the outer layers of granulosa cells of the follicle, causing a decrease in cyclic GMP in the granulosa cells. Because the granulosa cells and oocyte are connected by gap junctions, cyclic GMP also decreases in the oocyte, causing meiosis to resume. Meiosis then proceeds to second metaphase, where it pauses again until fertilization. Luteinizing hormone also stimulates gene expression leading to ovulation.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'reproduction-development', 'Oogenesis: In humans', 'In humans, oogenesis begins in embryonic development with the transformation of oogonia into primary oocytes, a process called oocytogenesis. From one single oogonium, only one mature oocyte will rise, with three other cells called polar bodies. Oocytogenesis is complete either before or shortly after birth.', 'Wikipedia: Oogenesis', 'https://en.wikipedia.org/w/index.php?title=Oogenesis&oldid=1381166131', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'reproduction-development' and body = 'In humans, oogenesis begins in embryonic development with the transformation of oogonia into primary oocytes, a process called oocytogenesis. From one single oogonium, only one mature oocyte will rise, with three other cells called polar bodies. Oocytogenesis is complete either before or shortly after birth.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'reproduction-development', 'Oogenesis: Number of primary oocytes', 'Primary oocytes reach their maximum development at ~20 weeks of gestational age, when approximately seven million primary oocytes have been created. At birth, this number has already been reduced to approximately 1-2 million. At puberty, the number of oocytes decreases even more to reach about 300,000, and only about 400–500 mature oocytes will be produced during a woman''s life, the others will undergo atresia (degeneration).', 'Wikipedia: Oogenesis', 'https://en.wikipedia.org/w/index.php?title=Oogenesis&oldid=1381166131', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'reproduction-development' and body = 'Primary oocytes reach their maximum development at ~20 weeks of gestational age, when approximately seven million primary oocytes have been created. At birth, this number has already been reduced to approximately 1-2 million. At puberty, the number of oocytes decreases even more to reach about 300,000, and only about 400–500 mature oocytes will be produced during a woman''s life, the others will undergo atresia (degeneration).');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'reproduction-development', 'Oogenesis: Ootidogenesis', 'The succeeding phase of ootidogenesis occurs when the primary oocyte undergoes meiosis to develop into an ootid stage of an immature ovum. Although this process begins at prenatal age, it stops at prophase I. In late fetal life, all oocytes, still primary oocytes, have halted at this stage of development, called the dictyate. After menarche, these cells then continue to develop, although only a few do so every menstrual cycle.', 'Wikipedia: Oogenesis', 'https://en.wikipedia.org/w/index.php?title=Oogenesis&oldid=1381166131', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'reproduction-development' and body = 'The succeeding phase of ootidogenesis occurs when the primary oocyte undergoes meiosis to develop into an ootid stage of an immature ovum. Although this process begins at prenatal age, it stops at prophase I. In late fetal life, all oocytes, still primary oocytes, have halted at this stage of development, called the dictyate. After menarche, these cells then continue to develop, although only a few do so every menstrual cycle.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'reproduction-development', 'Menstrual cycle', 'The menstrual cycle is a series of natural changes in hormone production and the structures of the uterus and ovaries of the female reproductive system that makes pregnancy possible. The ovarian cycle controls the production and release of eggs and the cyclic release of estrogen and progesterone. The uterine cycle governs the preparation and maintenance of the lining of the uterus (womb) to receive an embryo. These cycles are concurrent and coordinated, normally last between 21 and 35 days, with a median length of 28 days. Menarche (the onset of the first period) usually occurs around the age of 12 years; menstrual cycles continue for about 30–45 years. Naturally occurring hormones drive the cycles; the cyclical rise and fall of the follicle stimulating hormone prompts the production and growth of oocytes (immature egg cells). The hormone estrogen stimulates the uterus lining (endometrium) to thicken to accommodate an embryo should fertilization occur. The blood supply of the thickened lining provides nutrients to a successfully implanted embryo. If implantation does not occur, the lining breaks down and blood is released. Triggered by falling progesterone levels, menstruation (commonly referred to as a "period") is the cyclical shedding of the lining, and is a sign that pregnancy has not occurred.', 'Wikipedia: Menstrual cycle', 'https://en.wikipedia.org/w/index.php?title=Menstrual_cycle&oldid=1380615319', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'reproduction-development' and body = 'The menstrual cycle is a series of natural changes in hormone production and the structures of the uterus and ovaries of the female reproductive system that makes pregnancy possible. The ovarian cycle controls the production and release of eggs and the cyclic release of estrogen and progesterone. The uterine cycle governs the preparation and maintenance of the lining of the uterus (womb) to receive an embryo. These cycles are concurrent and coordinated, normally last between 21 and 35 days, with a median length of 28 days. Menarche (the onset of the first period) usually occurs around the age of 12 years; menstrual cycles continue for about 30–45 years. Naturally occurring hormones drive the cycles; the cyclical rise and fall of the follicle stimulating hormone prompts the production and growth of oocytes (immature egg cells). The hormone estrogen stimulates the uterus lining (endometrium) to thicken to accommodate an embryo should fertilization occur. The blood supply of the thickened lining provides nutrients to a successfully implanted embryo. If implantation does not occur, the lining breaks down and blood is released. Triggered by falling progesterone levels, menstruation (commonly referred to as a "period") is the cyclical shedding of the lining, and is a sign that pregnancy has not occurred.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'reproduction-development', 'Menstrual cycle', 'Each cycle occurs in phases based on events either in the ovary (ovarian cycle) or in the uterus (uterine cycle). The ovarian cycle consists of the follicular phase, ovulation, and the luteal phase; the uterine cycle consists of the menstrual, proliferative and secretory phases. Day one of the menstrual cycle is the first day of the period, which lasts for about 5 days. Around day fourteen, an egg is usually released from the ovary. The menstrual cycle can cause some women to experience premenstrual syndrome with symptoms that may include tender breasts, and tiredness. More severe symptoms that affect daily living are classed as premenstrual dysphoric disorder, and are experienced by 3–8% of women. During the first few days of menstruation some women experience period pain that can spread from the abdomen to the back and upper thighs. The menstrual cycle can be modified by hormonal birth control.', 'Wikipedia: Menstrual cycle', 'https://en.wikipedia.org/w/index.php?title=Menstrual_cycle&oldid=1380615319', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'reproduction-development' and body = 'Each cycle occurs in phases based on events either in the ovary (ovarian cycle) or in the uterus (uterine cycle). The ovarian cycle consists of the follicular phase, ovulation, and the luteal phase; the uterine cycle consists of the menstrual, proliferative and secretory phases. Day one of the menstrual cycle is the first day of the period, which lasts for about 5 days. Around day fourteen, an egg is usually released from the ovary. The menstrual cycle can cause some women to experience premenstrual syndrome with symptoms that may include tender breasts, and tiredness. More severe symptoms that affect daily living are classed as premenstrual dysphoric disorder, and are experienced by 3–8% of women. During the first few days of menstruation some women experience period pain that can spread from the abdomen to the back and upper thighs. The menstrual cycle can be modified by hormonal birth control.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'reproduction-development', 'Menstrual cycle: Cycles and phases', 'The menstrual cycle encompasses the ovarian and uterine cycles. The ovarian cycle describes changes that occur in the follicles of the ovary, whereas the uterine cycle describes changes in the endometrial lining of the uterus. Both cycles can be divided into phases. The ovarian cycle consists of alternating follicular and luteal phases, and the uterine cycle consists of the menstrual phase, the proliferative phase, and the secretory phase. The menstrual cycle is controlled by the hypothalamus in the brain, and the anterior pituitary gland at the base of the brain. The hypothalamus releases gonadotropin-releasing hormone (GnRH), which causes the nearby anterior pituitary to release follicle-stimulating hormone (FSH) and luteinizing hormone (LH). Before puberty, GnRH is released in low steady quantities and at a steady rate. After puberty, GnRH is released in large pulses, and the frequency and magnitude of these determine how much FSH and LH are produced by the pituitary.', 'Wikipedia: Menstrual cycle', 'https://en.wikipedia.org/w/index.php?title=Menstrual_cycle&oldid=1380615319', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'reproduction-development' and body = 'The menstrual cycle encompasses the ovarian and uterine cycles. The ovarian cycle describes changes that occur in the follicles of the ovary, whereas the uterine cycle describes changes in the endometrial lining of the uterus. Both cycles can be divided into phases. The ovarian cycle consists of alternating follicular and luteal phases, and the uterine cycle consists of the menstrual phase, the proliferative phase, and the secretory phase. The menstrual cycle is controlled by the hypothalamus in the brain, and the anterior pituitary gland at the base of the brain. The hypothalamus releases gonadotropin-releasing hormone (GnRH), which causes the nearby anterior pituitary to release follicle-stimulating hormone (FSH) and luteinizing hormone (LH). Before puberty, GnRH is released in low steady quantities and at a steady rate. After puberty, GnRH is released in large pulses, and the frequency and magnitude of these determine how much FSH and LH are produced by the pituitary.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'reproduction-development', 'Menstrual cycle: Cycles and phases', 'Measured from the first day of one menstruation to the first day of the next, the length of a menstrual cycle varies but has a median length of 28 days. The cycle is often less regular at the beginning and end of a woman''s reproductive life. At puberty, a child''s body begins to mature into an adult body capable of sexual reproduction; the first period (called menarche) occurs at around 12 years of age and continues for about 30–45 years. Menstrual cycles end at menopause, which is usually between 45 and 55 years of age.', 'Wikipedia: Menstrual cycle', 'https://en.wikipedia.org/w/index.php?title=Menstrual_cycle&oldid=1380615319', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'reproduction-development' and body = 'Measured from the first day of one menstruation to the first day of the next, the length of a menstrual cycle varies but has a median length of 28 days. The cycle is often less regular at the beginning and end of a woman''s reproductive life. At puberty, a child''s body begins to mature into an adult body capable of sexual reproduction; the first period (called menarche) occurs at around 12 years of age and continues for about 30–45 years. Menstrual cycles end at menopause, which is usually between 45 and 55 years of age.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'reproduction-development', 'Menstrual cycle: Ovarian cycle', 'Between menarche and menopause the ovaries regularly alternate between luteal and follicular phases during the monthly menstrual cycle. Stimulated by gradually increasing amounts of estrogen in the follicular phase, discharges of blood flow stop and the uterine lining thickens. Follicles in the ovary begin developing under the influence of a complex interplay of hormones, and after several days one, or occasionally two, become dominant, while non-dominant follicles shrink and die. About mid-cycle, some 10–12 hours after the increase in luteinizing hormone, known as the LH surge, the dominant follicle releases an oocyte, in an event called ovulation.', 'Wikipedia: Menstrual cycle', 'https://en.wikipedia.org/w/index.php?title=Menstrual_cycle&oldid=1380615319', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'reproduction-development' and body = 'Between menarche and menopause the ovaries regularly alternate between luteal and follicular phases during the monthly menstrual cycle. Stimulated by gradually increasing amounts of estrogen in the follicular phase, discharges of blood flow stop and the uterine lining thickens. Follicles in the ovary begin developing under the influence of a complex interplay of hormones, and after several days one, or occasionally two, become dominant, while non-dominant follicles shrink and die. About mid-cycle, some 10–12 hours after the increase in luteinizing hormone, known as the LH surge, the dominant follicle releases an oocyte, in an event called ovulation.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'reproduction-development', 'Menstrual cycle: Ovarian cycle', 'After ovulation, the oocyte lives for 24 hours or less without fertilization, while the remains of the dominant follicle in the ovary become a corpus luteum – a body with the primary function of producing large amounts of the hormone progesterone. Under the influence of progesterone, the uterine lining changes to prepare for potential implantation of an embryo to establish a pregnancy. The thickness of the endometrium continues to increase in response to mounting levels of estrogen, which is released by the antral follicle (a mature ovarian follicle) into the blood circulation. Peak levels of estrogen are reached at around day thirteen of the cycle and coincide with ovulation. If implantation does not occur within about two weeks, the corpus luteum degenerates into the corpus albicans, which does not produce hormones, causing a sharp drop in levels of both progesterone and estrogen. This drop causes the uterus to lose its lining in menstruation; it is around this time that the lowest levels of estrogen are reached.', 'Wikipedia: Menstrual cycle', 'https://en.wikipedia.org/w/index.php?title=Menstrual_cycle&oldid=1380615319', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'reproduction-development' and body = 'After ovulation, the oocyte lives for 24 hours or less without fertilization, while the remains of the dominant follicle in the ovary become a corpus luteum – a body with the primary function of producing large amounts of the hormone progesterone. Under the influence of progesterone, the uterine lining changes to prepare for potential implantation of an embryo to establish a pregnancy. The thickness of the endometrium continues to increase in response to mounting levels of estrogen, which is released by the antral follicle (a mature ovarian follicle) into the blood circulation. Peak levels of estrogen are reached at around day thirteen of the cycle and coincide with ovulation. If implantation does not occur within about two weeks, the corpus luteum degenerates into the corpus albicans, which does not produce hormones, causing a sharp drop in levels of both progesterone and estrogen. This drop causes the uterus to lose its lining in menstruation; it is around this time that the lowest levels of estrogen are reached.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'reproduction-development', 'Menstrual cycle: Ovarian cycle', 'In an ovulatory menstrual cycle, the ovarian and uterine cycles are concurrent and coordinated and last between 21 and 35 days, with a population average of 27–29 days. The average length of the human menstrual cycle is similar to that of the lunar cycle. Some studies have suggested that the menstrual cycle is synchronized with the lunar cycle, though the mainstream view is that they are unrelated.', 'Wikipedia: Menstrual cycle', 'https://en.wikipedia.org/w/index.php?title=Menstrual_cycle&oldid=1380615319', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'reproduction-development' and body = 'In an ovulatory menstrual cycle, the ovarian and uterine cycles are concurrent and coordinated and last between 21 and 35 days, with a population average of 27–29 days. The average length of the human menstrual cycle is similar to that of the lunar cycle. Some studies have suggested that the menstrual cycle is synchronized with the lunar cycle, though the mainstream view is that they are unrelated.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'reproduction-development', 'Menstrual cycle: Follicular phase', 'The ovaries contain a finite number of immature egg cells, and granulosa cells, which together form primordial follicles. When the follicle matures into a secondary follicle,theca cells enter from the surrounding tissue. At around 20 weeks into gestation some 7 million immature eggs have already formed in an ovary. This decreases to around 2 million by the time a girl is born, and 300,000 by the time she has her first period. On average, one egg matures and is released during ovulation each month after menarche. Beginning at puberty, these mature to primary follicles independently of the menstrual cycle. The development of the egg is called oogenesis and only one cell survives the divisions to await fertilization. The other cells are discarded as polar bodies, which cannot be fertilized. The follicular phase is the first part of the ovarian cycle and it ends with the completion of the antral follicles. Meiosis (cell division) remains incomplete in the egg cells until the antral follicle is formed. During this phase usually only one ovarian follicle fully matures and gets ready to release an egg. The follicular phase shortens significantly with age, lasting around 14 days in women aged 18–24 compared with 10 days in women aged 40–44.', 'Wikipedia: Menstrual cycle', 'https://en.wikipedia.org/w/index.php?title=Menstrual_cycle&oldid=1380615319', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'reproduction-development' and body = 'The ovaries contain a finite number of immature egg cells, and granulosa cells, which together form primordial follicles. When the follicle matures into a secondary follicle,theca cells enter from the surrounding tissue. At around 20 weeks into gestation some 7 million immature eggs have already formed in an ovary. This decreases to around 2 million by the time a girl is born, and 300,000 by the time she has her first period. On average, one egg matures and is released during ovulation each month after menarche. Beginning at puberty, these mature to primary follicles independently of the menstrual cycle. The development of the egg is called oogenesis and only one cell survives the divisions to await fertilization. The other cells are discarded as polar bodies, which cannot be fertilized. The follicular phase is the first part of the ovarian cycle and it ends with the completion of the antral follicles. Meiosis (cell division) remains incomplete in the egg cells until the antral follicle is formed. During this phase usually only one ovarian follicle fully matures and gets ready to release an egg. The follicular phase shortens significantly with age, lasting around 14 days in women aged 18–24 compared with 10 days in women aged 40–44.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'reproduction-development', 'Fertilisation', 'Fertilisation or fertilization (see spelling differences), also known as generative fertilisation, syngamy and impregnation, is the fusion of gametes to give rise to a zygote and initiate its development into a new individual organism or offspring. While processes such as insemination or pollination, which happen before the fusion of gametes, are also sometimes informally referred to as fertilisation, these are technically separate processes. The cycle of fertilisation and development of new individuals is called sexual reproduction. During double fertilisation in angiosperms, the haploid male gamete combines with two haploid polar nuclei to form a triploid primary endosperm nucleus by the process of vegetative fertilisation.', 'Wikipedia: Fertilisation', 'https://en.wikipedia.org/w/index.php?title=Fertilisation&oldid=1380173187', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'reproduction-development' and body = 'Fertilisation or fertilization (see spelling differences), also known as generative fertilisation, syngamy and impregnation, is the fusion of gametes to give rise to a zygote and initiate its development into a new individual organism or offspring. While processes such as insemination or pollination, which happen before the fusion of gametes, are also sometimes informally referred to as fertilisation, these are technically separate processes. The cycle of fertilisation and development of new individuals is called sexual reproduction. During double fertilisation in angiosperms, the haploid male gamete combines with two haploid polar nuclei to form a triploid primary endosperm nucleus by the process of vegetative fertilisation.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'reproduction-development', 'Fertilisation: Discovery', 'In antiquity, Aristotle conceived the formation of new individuals through fusion of male and female fluids, with form and function emerging gradually, in a mode called by him as epigenetic. In 1784, Spallanzani established the need of interaction between the female''s ovum and male''s sperm to form a zygote in frogs. In 1827, Karl Ernst von Baer observed a therian mammalian egg for the first time. Oscar Hertwig (1876), in Germany, described the fusion of nuclei of spermatozoa and of ova of sea urchins.', 'Wikipedia: Fertilisation', 'https://en.wikipedia.org/w/index.php?title=Fertilisation&oldid=1380173187', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'reproduction-development' and body = 'In antiquity, Aristotle conceived the formation of new individuals through fusion of male and female fluids, with form and function emerging gradually, in a mode called by him as epigenetic. In 1784, Spallanzani established the need of interaction between the female''s ovum and male''s sperm to form a zygote in frogs. In 1827, Karl Ernst von Baer observed a therian mammalian egg for the first time. Oscar Hertwig (1876), in Germany, described the fusion of nuclei of spermatozoa and of ova of sea urchins.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'reproduction-development', 'Fertilisation: Evolution', 'The evolution of fertilisation is related to the origin of meiosis, as both are part of sexual reproduction, originated in eukaryotes. One hypothesis states that meiosis originated from mitosis.', 'Wikipedia: Fertilisation', 'https://en.wikipedia.org/w/index.php?title=Fertilisation&oldid=1380173187', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'reproduction-development' and body = 'The evolution of fertilisation is related to the origin of meiosis, as both are part of sexual reproduction, originated in eukaryotes. One hypothesis states that meiosis originated from mitosis.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'reproduction-development', 'Fertilisation: Fertilisation in plants', 'The gametes that participate in fertilisation of plants are the sperm (male) and the egg (female) cell. Various plant groups have differing methods by which the gametes produced by the male and female gametophytes come together and are fertilised. In bryophytes and pteridophytic land plants, fertilisation of the sperm and egg takes place within the archegonium. In seed plants, the male gametophyte is formed within a pollen grain. After pollination, the pollen grain germinates, and a pollen tube grows and penetrates the ovule through a tiny pore called a micropyle. The sperm are transferred from the pollen through the pollen tube to the ovule where the egg is fertilised. In flowering plants, two sperm cells are released from the pollen tube, and a second fertilisation event occurs involving the second sperm cell and the central cell of the ovule, which is a second female gamete.', 'Wikipedia: Fertilisation', 'https://en.wikipedia.org/w/index.php?title=Fertilisation&oldid=1380173187', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'reproduction-development' and body = 'The gametes that participate in fertilisation of plants are the sperm (male) and the egg (female) cell. Various plant groups have differing methods by which the gametes produced by the male and female gametophytes come together and are fertilised. In bryophytes and pteridophytic land plants, fertilisation of the sperm and egg takes place within the archegonium. In seed plants, the male gametophyte is formed within a pollen grain. After pollination, the pollen grain germinates, and a pollen tube grows and penetrates the ovule through a tiny pore called a micropyle. The sperm are transferred from the pollen through the pollen tube to the ovule where the egg is fertilised. In flowering plants, two sperm cells are released from the pollen tube, and a second fertilisation event occurs involving the second sperm cell and the central cell of the ovule, which is a second female gamete.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'reproduction-development', 'Fertilisation: Pollen tube growth', 'Unlike animal sperm which is motile, the sperm of most seed plants is immotile and relies on the pollen tube to carry it to the ovule where the sperm is released. The pollen tube penetrates the stigma and elongates through the extracellular matrix of the style before reaching the ovary. Then near the receptacle, it breaks through the ovule through the micropyle (an opening in the ovule wall) and the pollen tube "bursts" into the embryo sac, releasing sperm. The growth of the pollen tube has been believed to depend on chemical cues from the pistil, however these mechanisms were poorly understood until 1995. Work done on tobacco plants revealed a family of glycoproteins called TTS proteins that enhanced growth of pollen tubes. Pollen tubes in a sugar free pollen germination medium and a medium with purified TTS proteins both grew. However, in the TTS medium, the tubes grew at a rate 3x that of the sugar-free medium. TTS proteins were also placed on various locations of semi in vivo pollinated pistils, and pollen tubes were observed to immediately extend toward the proteins. Transgenic plants lacking the ability to produce TTS proteins had slower pollen tube growth and reduced fertility.', 'Wikipedia: Fertilisation', 'https://en.wikipedia.org/w/index.php?title=Fertilisation&oldid=1380173187', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'reproduction-development' and body = 'Unlike animal sperm which is motile, the sperm of most seed plants is immotile and relies on the pollen tube to carry it to the ovule where the sperm is released. The pollen tube penetrates the stigma and elongates through the extracellular matrix of the style before reaching the ovary. Then near the receptacle, it breaks through the ovule through the micropyle (an opening in the ovule wall) and the pollen tube "bursts" into the embryo sac, releasing sperm. The growth of the pollen tube has been believed to depend on chemical cues from the pistil, however these mechanisms were poorly understood until 1995. Work done on tobacco plants revealed a family of glycoproteins called TTS proteins that enhanced growth of pollen tubes. Pollen tubes in a sugar free pollen germination medium and a medium with purified TTS proteins both grew. However, in the TTS medium, the tubes grew at a rate 3x that of the sugar-free medium. TTS proteins were also placed on various locations of semi in vivo pollinated pistils, and pollen tubes were observed to immediately extend toward the proteins. Transgenic plants lacking the ability to produce TTS proteins had slower pollen tube growth and reduced fertility.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'reproduction-development', 'Fertilisation: Rupture of pollen tube', 'The rupture of the pollen tube to release sperm in Arabidopsis has been shown to depend on a signal from the female gametophyte. Specific proteins called FER protein kinases present in the ovule control the production of highly reactive derivatives of oxygen called reactive oxygen species (ROS). ROS levels have been shown via GFP to be at their highest during floral stages when the ovule is the most receptive to pollen tubes, and lowest during times of development and following fertilisation. High amounts of ROS activate calcium ion channels in the pollen tube, causing these channels to take up calcium ions in large amounts. This increased uptake of calcium causes the pollen tube to rupture, and release its sperm into the ovule. Pistil feeding assays in which plants were fed diphenyl iodonium chloride (DPI) suppressed ROS concentrations in Arabidopsis, which in turn prevented pollen tube rupture.', 'Wikipedia: Fertilisation', 'https://en.wikipedia.org/w/index.php?title=Fertilisation&oldid=1380173187', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'reproduction-development' and body = 'The rupture of the pollen tube to release sperm in Arabidopsis has been shown to depend on a signal from the female gametophyte. Specific proteins called FER protein kinases present in the ovule control the production of highly reactive derivatives of oxygen called reactive oxygen species (ROS). ROS levels have been shown via GFP to be at their highest during floral stages when the ovule is the most receptive to pollen tubes, and lowest during times of development and following fertilisation. High amounts of ROS activate calcium ion channels in the pollen tube, causing these channels to take up calcium ions in large amounts. This increased uptake of calcium causes the pollen tube to rupture, and release its sperm into the ovule. Pistil feeding assays in which plants were fed diphenyl iodonium chloride (DPI) suppressed ROS concentrations in Arabidopsis, which in turn prevented pollen tube rupture.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'reproduction-development', 'Fertilisation: Flowering plants', 'After being fertilised, the ovary starts to swell and develop into the fruit. With multi-seeded fruits, multiple grains of pollen are necessary for syngamy with each ovule. The growth of the pollen tube is controlled by the vegetative (or tube) cytoplasm. Hydrolytic enzymes are secreted by the pollen tube that digest the female tissue as the tube grows down the stigma and style; the digested tissue is used as a nutrient source for the pollen tube as it grows. During pollen tube growth towards the ovary, the generative nucleus divides to produce two separate sperm nuclei (haploid number of chromosomes) – a growing pollen tube therefore contains three separate nuclei, two sperm and one tube. The sperms are interconnected and dimorphic, the large one, in a number of plants, is also linked to the tube nucleus and the interconnected sperm and the tube nucleus form the "male germ unit".', 'Wikipedia: Fertilisation', 'https://en.wikipedia.org/w/index.php?title=Fertilisation&oldid=1380173187', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'reproduction-development' and body = 'After being fertilised, the ovary starts to swell and develop into the fruit. With multi-seeded fruits, multiple grains of pollen are necessary for syngamy with each ovule. The growth of the pollen tube is controlled by the vegetative (or tube) cytoplasm. Hydrolytic enzymes are secreted by the pollen tube that digest the female tissue as the tube grows down the stigma and style; the digested tissue is used as a nutrient source for the pollen tube as it grows. During pollen tube growth towards the ovary, the generative nucleus divides to produce two separate sperm nuclei (haploid number of chromosomes) – a growing pollen tube therefore contains three separate nuclei, two sperm and one tube. The sperms are interconnected and dimorphic, the large one, in a number of plants, is also linked to the tube nucleus and the interconnected sperm and the tube nucleus form the "male germ unit".');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'reproduction-development', 'Fertilisation: Flowering plants', 'Double fertilisation is the process in angiosperms (flowering plants) in which two sperm from each pollen tube fertilise two cells in a female gametophyte (sometimes called an embryo sac) that is inside an ovule. After the pollen tube enters the gametophyte, the pollen tube nucleus disintegrates and the two sperm cells are released; one of the two sperm cells fertilises the egg cell (at the bottom of the gametophyte near the micropyle), forming a diploid (2n) zygote. This is the point when fertilisation actually occurs; pollination and fertilisation are two separate processes. The nucleus of the other sperm cell fuses with two haploid polar nuclei (contained in the central cell) in the centre of the gametophyte. The resulting cell is triploid (3n). This triploid cell divides through mitosis and forms the endosperm, a nutrient-rich tissue, inside the seed. The two central-cell maternal nuclei (polar nuclei) that contribute to the endosperm arise by mitosis from the single meiotic product that also gave rise to the egg. Therefore, maternal contribution to the genetic constitution of the triploid endosperm is double that of the embryo.', 'Wikipedia: Fertilisation', 'https://en.wikipedia.org/w/index.php?title=Fertilisation&oldid=1380173187', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'reproduction-development' and body = 'Double fertilisation is the process in angiosperms (flowering plants) in which two sperm from each pollen tube fertilise two cells in a female gametophyte (sometimes called an embryo sac) that is inside an ovule. After the pollen tube enters the gametophyte, the pollen tube nucleus disintegrates and the two sperm cells are released; one of the two sperm cells fertilises the egg cell (at the bottom of the gametophyte near the micropyle), forming a diploid (2n) zygote. This is the point when fertilisation actually occurs; pollination and fertilisation are two separate processes. The nucleus of the other sperm cell fuses with two haploid polar nuclei (contained in the central cell) in the centre of the gametophyte. The resulting cell is triploid (3n). This triploid cell divides through mitosis and forms the endosperm, a nutrient-rich tissue, inside the seed. The two central-cell maternal nuclei (polar nuclei) that contribute to the endosperm arise by mitosis from the single meiotic product that also gave rise to the egg. Therefore, maternal contribution to the genetic constitution of the triploid endosperm is double that of the embryo.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'reproduction-development', 'Human embryonic development', 'Human embryonic development or human embryogenesis is the development and formation of the human embryo. It is characterised by the processes of cell division and cellular differentiation of the embryo that occurs during the early stages of development. In biological terms, the development of the human body entails growth from a one-celled zygote to an adult human being. Fertilization occurs when the sperm cell successfully enters and fuses with an egg cell (ovum). The genetic material of the sperm and egg then combine to form the single cell zygote and the germinal stage of development commences. Human embryonic development covers the first eight weeks of development, which have 23 stages, called Carnegie stages. At the beginning of the ninth week, the embryo is termed a fetus (spelled "foetus" in British English). In comparison to the embryo, the fetus has more recognizable external features and a more complete set of developing organs. Human embryology is the study of this development during the first eight weeks after fertilization. The normal period of gestation (pregnancy) is about nine months or 40 weeks.', 'Wikipedia: Human embryonic development', 'https://en.wikipedia.org/w/index.php?title=Human_embryonic_development&oldid=1380086129', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'reproduction-development' and body = 'Human embryonic development or human embryogenesis is the development and formation of the human embryo. It is characterised by the processes of cell division and cellular differentiation of the embryo that occurs during the early stages of development. In biological terms, the development of the human body entails growth from a one-celled zygote to an adult human being. Fertilization occurs when the sperm cell successfully enters and fuses with an egg cell (ovum). The genetic material of the sperm and egg then combine to form the single cell zygote and the germinal stage of development commences. Human embryonic development covers the first eight weeks of development, which have 23 stages, called Carnegie stages. At the beginning of the ninth week, the embryo is termed a fetus (spelled "foetus" in British English). In comparison to the embryo, the fetus has more recognizable external features and a more complete set of developing organs. Human embryology is the study of this development during the first eight weeks after fertilization. The normal period of gestation (pregnancy) is about nine months or 40 weeks.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'reproduction-development', 'Human embryonic development', 'The germinal stage refers to the time from fertilization through the development of the early embryo until implantation is completed in the uterus. The germinal stage takes around 10 days. During this stage, the zygote divides in a process called cleavage. A blastocyst is then formed and implants in the uterus. Embryogenesis continues with the next stage of gastrulation, when the three germ layers of the embryo are formed. The processes of histogenesis, neurulation, and organogenesis follow. The entire process of embryogenesis involves coordinated spatial and temporal changes in gene expression, cell growth, and cellular differentiation. A nearly identical process occurs in other species, especially among chordates.', 'Wikipedia: Human embryonic development', 'https://en.wikipedia.org/w/index.php?title=Human_embryonic_development&oldid=1380086129', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'reproduction-development' and body = 'The germinal stage refers to the time from fertilization through the development of the early embryo until implantation is completed in the uterus. The germinal stage takes around 10 days. During this stage, the zygote divides in a process called cleavage. A blastocyst is then formed and implants in the uterus. Embryogenesis continues with the next stage of gastrulation, when the three germ layers of the embryo are formed. The processes of histogenesis, neurulation, and organogenesis follow. The entire process of embryogenesis involves coordinated spatial and temporal changes in gene expression, cell growth, and cellular differentiation. A nearly identical process occurs in other species, especially among chordates.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'reproduction-development', 'Human embryonic development: Fertilization', 'Fertilization takes place when the spermatozoon has successfully entered the ovum and the two sets of genetic material carried by the gametes fuse together, resulting in the zygote (a single diploid cell). This usually takes place in the ampulla of one of the fallopian tubes. The zygote contains the combined genetic material carried by both the male and female gametes which consists of the 23 chromosomes from the nucleus of the ovum and the 23 chromosomes from the nucleus of the sperm. The 46 chromosomes undergo changes prior to the mitotic division which leads to the formation of the embryo having two cells.', 'Wikipedia: Human embryonic development', 'https://en.wikipedia.org/w/index.php?title=Human_embryonic_development&oldid=1380086129', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'reproduction-development' and body = 'Fertilization takes place when the spermatozoon has successfully entered the ovum and the two sets of genetic material carried by the gametes fuse together, resulting in the zygote (a single diploid cell). This usually takes place in the ampulla of one of the fallopian tubes. The zygote contains the combined genetic material carried by both the male and female gametes which consists of the 23 chromosomes from the nucleus of the ovum and the 23 chromosomes from the nucleus of the sperm. The 46 chromosomes undergo changes prior to the mitotic division which leads to the formation of the embryo having two cells.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'reproduction-development', 'Human embryonic development: Fertilization', 'Successful fertilization is enabled by three processes, which also act as controls to ensure species-specificity. The first is that of chemotaxis which directs the movement of the sperm towards the ovum. Secondly, an adhesive compatibility between the sperm and the egg occurs. With the sperm adhered to the ovum, the third process of acrosomal reaction takes place; the front part of the spermatozoan head is capped by an acrosome which contains digestive enzymes to break down the zona pellucida and allow its entry. The entry of the sperm causes calcium to be released which blocks entry to other sperm cells. A parallel reaction takes place in the ovum called the zona reaction. This sees the release of cortical granules that release enzymes which digest sperm receptor proteins, thus preventing polyspermy. The granules also fuse with the plasma membrane and modify the zona pellucida in such a way as to prevent further sperm entry.', 'Wikipedia: Human embryonic development', 'https://en.wikipedia.org/w/index.php?title=Human_embryonic_development&oldid=1380086129', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'reproduction-development' and body = 'Successful fertilization is enabled by three processes, which also act as controls to ensure species-specificity. The first is that of chemotaxis which directs the movement of the sperm towards the ovum. Secondly, an adhesive compatibility between the sperm and the egg occurs. With the sperm adhered to the ovum, the third process of acrosomal reaction takes place; the front part of the spermatozoan head is capped by an acrosome which contains digestive enzymes to break down the zona pellucida and allow its entry. The entry of the sperm causes calcium to be released which blocks entry to other sperm cells. A parallel reaction takes place in the ovum called the zona reaction. This sees the release of cortical granules that release enzymes which digest sperm receptor proteins, thus preventing polyspermy. The granules also fuse with the plasma membrane and modify the zona pellucida in such a way as to prevent further sperm entry.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'reproduction-development', 'Human embryonic development: Cleavage', 'The beginning of the cleavage process is marked when the zygote divides through mitosis into two cells. This mitosis continues and the first two cells divide into four cells, then into eight cells and so on. Each division takes from 12 to 24 hours. The zygote is large compared to any other cell and undergoes cleavage without any overall increase in size. This means that with each successive subdivision, the ratio of nuclear to cytoplasmic material increases. Initially, the dividing cells, called blastomeres (blastos Greek for sprout), are undifferentiated and aggregated into a sphere enclosed within the zona pellucida of the ovum. When eight blastomeres have formed, they start to compact. They begin to develop gap junctions, enabling them to develop in an integrated way and co-ordinate their response to physiological signals and environmental cues. When the cells number around sixteen, the solid sphere of cells within the zona pellucida is referred to as a morula.', 'Wikipedia: Human embryonic development', 'https://en.wikipedia.org/w/index.php?title=Human_embryonic_development&oldid=1380086129', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'reproduction-development' and body = 'The beginning of the cleavage process is marked when the zygote divides through mitosis into two cells. This mitosis continues and the first two cells divide into four cells, then into eight cells and so on. Each division takes from 12 to 24 hours. The zygote is large compared to any other cell and undergoes cleavage without any overall increase in size. This means that with each successive subdivision, the ratio of nuclear to cytoplasmic material increases. Initially, the dividing cells, called blastomeres (blastos Greek for sprout), are undifferentiated and aggregated into a sphere enclosed within the zona pellucida of the ovum. When eight blastomeres have formed, they start to compact. They begin to develop gap junctions, enabling them to develop in an integrated way and co-ordinate their response to physiological signals and environmental cues. When the cells number around sixteen, the solid sphere of cells within the zona pellucida is referred to as a morula.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'reproduction-development', 'Human embryonic development: Blastulation', 'Cleavage itself is the first stage in blastulation, the process of forming the blastocyst. Cells differentiate into an outer layer of cells called the trophoblast, and an inner cell mass. With further compaction the individual outer blastomeres, the trophoblasts, become indistinguishable. They are still enclosed within the zona pellucida. This compaction serves to make the structure watertight, containing the fluid that the cells will later secrete. The inner mass of cells differentiate to become embryoblasts and polarise at one end. They close together and form gap junctions, which facilitate cellular communication. This polarisation leaves a cavity, the blastocoel, creating a structure that is now termed the blastocyst. (In animals other than mammals, this is called the blastula).', 'Wikipedia: Human embryonic development', 'https://en.wikipedia.org/w/index.php?title=Human_embryonic_development&oldid=1380086129', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'reproduction-development' and body = 'Cleavage itself is the first stage in blastulation, the process of forming the blastocyst. Cells differentiate into an outer layer of cells called the trophoblast, and an inner cell mass. With further compaction the individual outer blastomeres, the trophoblasts, become indistinguishable. They are still enclosed within the zona pellucida. This compaction serves to make the structure watertight, containing the fluid that the cells will later secrete. The inner mass of cells differentiate to become embryoblasts and polarise at one end. They close together and form gap junctions, which facilitate cellular communication. This polarisation leaves a cavity, the blastocoel, creating a structure that is now termed the blastocyst. (In animals other than mammals, this is called the blastula).');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'reproduction-development', 'Human embryonic development: Blastulation', 'The trophoblasts secrete fluid into the blastocoel. The resulting increase in size of the blastocyst causes it to hatch through the zona pellucida, which then disintegrates. This process is called zona hatching and it takes place on the sixth day of embryo development, immediately before the implantation process. The hatching of the human embryo is supported by proteases secreted by the cells of the blastocyst, which digest proteins of the zona pellucida, giving rise to a hole. Then, due to the rhythmic expansion and contractions of the blastocyst, an increase of the pressure inside the blastocyst itself occurs, the hole expands and finally the blastocyst can emerge from this rigid envelope. The inner cell mass will give rise to the pre-embryo, the amnion, yolk sac and allantois, while the fetal part of the placenta will form from the outer trophoblast layer. The embryo plus its membranes is called the conceptus, and by this stage the conceptus has reached the uterus. The zona pellucida ultimately disappears completely, and the now exposed cells of the trophoblast allow the blastocyst to attach itself to the endometrium, where it will implant.', 'Wikipedia: Human embryonic development', 'https://en.wikipedia.org/w/index.php?title=Human_embryonic_development&oldid=1380086129', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'reproduction-development' and body = 'The trophoblasts secrete fluid into the blastocoel. The resulting increase in size of the blastocyst causes it to hatch through the zona pellucida, which then disintegrates. This process is called zona hatching and it takes place on the sixth day of embryo development, immediately before the implantation process. The hatching of the human embryo is supported by proteases secreted by the cells of the blastocyst, which digest proteins of the zona pellucida, giving rise to a hole. Then, due to the rhythmic expansion and contractions of the blastocyst, an increase of the pressure inside the blastocyst itself occurs, the hole expands and finally the blastocyst can emerge from this rigid envelope. The inner cell mass will give rise to the pre-embryo, the amnion, yolk sac and allantois, while the fetal part of the placenta will form from the outer trophoblast layer. The embryo plus its membranes is called the conceptus, and by this stage the conceptus has reached the uterus. The zona pellucida ultimately disappears completely, and the now exposed cells of the trophoblast allow the blastocyst to attach itself to the endometrium, where it will implant.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'reproduction-development', 'Human embryonic development: Blastulation', 'The formation of the hypoblast and epiblast, which are the two main layers of the bilaminar germ disc, occurs at the beginning of the second week. Both the embryoblast and the trophoblast will turn into two sub-layers. The inner cells will turn into the hypoblast layer, which will surround the other layer, called the epiblast, and these layers will form the embryonic disc that will develop into the embryo.', 'Wikipedia: Human embryonic development', 'https://en.wikipedia.org/w/index.php?title=Human_embryonic_development&oldid=1380086129', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'reproduction-development' and body = 'The formation of the hypoblast and epiblast, which are the two main layers of the bilaminar germ disc, occurs at the beginning of the second week. Both the embryoblast and the trophoblast will turn into two sub-layers. The inner cells will turn into the hypoblast layer, which will surround the other layer, called the epiblast, and these layers will form the embryonic disc that will develop into the embryo.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'reproduction-development', 'Germ layer', 'A germ layer, primary germinal layer, or germinal layer is a primary layer of cells that forms during animal embryonic development. Germ layers form during gastrulation, when the early embryo is formed of two or three layers of cells. Sponges do not have a gastrulation stage and possess no true germ layers. They do though have two layers of cells separated by a gel-like mesohyl. Some aquatic invertebrates such as cnidarians, and comb jellies, develop from only two germ layers, an ectoderm and an endoderm, and are known as diploblasts. But most animals have a bilateral symmetry, and develop from three germ layers, an ectoderm, endoderm, and a middle layer of mesoderm, and are triploblastic. Germ layers eventually give rise to all of an animal''s tissues and organs through the processes of histogenesis, and organogenesis.', 'Wikipedia: Germ layer', 'https://en.wikipedia.org/w/index.php?title=Germ_layer&oldid=1353509923', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'reproduction-development' and body = 'A germ layer, primary germinal layer, or germinal layer is a primary layer of cells that forms during animal embryonic development. Germ layers form during gastrulation, when the early embryo is formed of two or three layers of cells. Sponges do not have a gastrulation stage and possess no true germ layers. They do though have two layers of cells separated by a gel-like mesohyl. Some aquatic invertebrates such as cnidarians, and comb jellies, develop from only two germ layers, an ectoderm and an endoderm, and are known as diploblasts. But most animals have a bilateral symmetry, and develop from three germ layers, an ectoderm, endoderm, and a middle layer of mesoderm, and are triploblastic. Germ layers eventually give rise to all of an animal''s tissues and organs through the processes of histogenesis, and organogenesis.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'reproduction-development', 'Germ layer: Evolution', 'Among animals, sponges do not have a gastrula stage and have no true germ layers, though they do have two layers of cells separated by a middle gel-like layer the mesohyl. Diploblastic animals, Cnidaria and Ctenophora, show an increase in compartmentalization, and have two germ layers, the endoderm and ectoderm. Diploblastic animals are organized into recognisable tissues. All other animals are bilaterian and triploblasts having a third middle layer of mesoderm between the other two. Triploblastic animals develop recognizable organs.', 'Wikipedia: Germ layer', 'https://en.wikipedia.org/w/index.php?title=Germ_layer&oldid=1353509923', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'reproduction-development' and body = 'Among animals, sponges do not have a gastrula stage and have no true germ layers, though they do have two layers of cells separated by a middle gel-like layer the mesohyl. Diploblastic animals, Cnidaria and Ctenophora, show an increase in compartmentalization, and have two germ layers, the endoderm and ectoderm. Diploblastic animals are organized into recognisable tissues. All other animals are bilaterian and triploblasts having a third middle layer of mesoderm between the other two. Triploblastic animals develop recognizable organs.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'reproduction-development', 'Germ layer: Development', 'Fertilization leads to the formation of a zygote. During the next stage, cleavage, mitotic cell divisions transform the zygote into a hollow ball of cells, a blastula. This early embryonic form undergoes gastrulation, forming a gastrula with either two or three layers (the germ layers). In all vertebrates, these progenitor cells differentiate into all adult tissues and organs. In the human embryo, after about three days, the zygote forms a solid mass of cells by mitotic division, called a morula. This then changes to a blastocyst, consisting of an outer layer called a trophoblast, and an inner cell mass called the embryoblast. Filled with uterine fluid, the blastocyst breaks out of the zona pellucida and undergoes implantation. The inner cell mass initially has two layers: the hypoblast and epiblast. At the end of the second week, a primitive streak appears. The epiblast in this region moves towards the primitive streak, dives down into it, and forms a new layer, called the endoderm, pushing the hypoblast out of the way (this goes on to form the amnion.) The epiblast keeps moving and forms a second layer, the mesoderm. The top layer is now called the ectoderm.', 'Wikipedia: Germ layer', 'https://en.wikipedia.org/w/index.php?title=Germ_layer&oldid=1353509923', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'reproduction-development' and body = 'Fertilization leads to the formation of a zygote. During the next stage, cleavage, mitotic cell divisions transform the zygote into a hollow ball of cells, a blastula. This early embryonic form undergoes gastrulation, forming a gastrula with either two or three layers (the germ layers). In all vertebrates, these progenitor cells differentiate into all adult tissues and organs. In the human embryo, after about three days, the zygote forms a solid mass of cells by mitotic division, called a morula. This then changes to a blastocyst, consisting of an outer layer called a trophoblast, and an inner cell mass called the embryoblast. Filled with uterine fluid, the blastocyst breaks out of the zona pellucida and undergoes implantation. The inner cell mass initially has two layers: the hypoblast and epiblast. At the end of the second week, a primitive streak appears. The epiblast in this region moves towards the primitive streak, dives down into it, and forms a new layer, called the endoderm, pushing the hypoblast out of the way (this goes on to form the amnion.) The epiblast keeps moving and forms a second layer, the mesoderm. The top layer is now called the ectoderm.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'reproduction-development', 'Germ layer: Development', 'Gastrulation occurs in reference to the primary body axis. Germ layer formation is linked to the primary body axis as well, however it is less reliant on it than gastrulation is. Hydractinia shows that germ layer formation that transpires as a mixed delamination. In mice, germ layer differentiation is controlled by two transcription factors: Sox2 and Oct4 proteins. These transcription factors cause the pluripotent mouse embryonic stem cells to select a germ layer fate. Sox2 promotes ectodermal differentiation, while Oct4 promotes mesendodermal differentiation. Each gene inhibits what the other promotes. Amounts of each protein are different throughout the genome, causing the embryonic stem cells to select their fate.', 'Wikipedia: Germ layer', 'https://en.wikipedia.org/w/index.php?title=Germ_layer&oldid=1353509923', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'reproduction-development' and body = 'Gastrulation occurs in reference to the primary body axis. Germ layer formation is linked to the primary body axis as well, however it is less reliant on it than gastrulation is. Hydractinia shows that germ layer formation that transpires as a mixed delamination. In mice, germ layer differentiation is controlled by two transcription factors: Sox2 and Oct4 proteins. These transcription factors cause the pluripotent mouse embryonic stem cells to select a germ layer fate. Sox2 promotes ectodermal differentiation, while Oct4 promotes mesendodermal differentiation. Each gene inhibits what the other promotes. Amounts of each protein are different throughout the genome, causing the embryonic stem cells to select their fate.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'reproduction-development', 'Germ layer: Endoderm', 'The endoderm is one of the germ layers formed during animal embryonic development. Cells migrate inward along the archenteron to form the inner layer of the gastrula, developing into the endoderm. The endoderm consists at first of flattened cells, which subsequently become columnar. It forms the epithelial lining of the whole of the digestive tract except part of the mouth and pharynx and the terminal part of the rectum (which are lined by involutions of the ectoderm). It also forms the lining cells of all the glands which open into the digestive tract, including those of the liver and pancreas; the epithelium of the auditory tube and tympanic cavity; the trachea, bronchi, and alveoli of the lungs; the bladder and part of the urethra; and the follicle lining of the thyroid gland and thymus. The endoderm forms the pharynx, the esophagus, the stomach, the small intestine, the colon, the liver, the pancreas, the bladder, the epithelial parts of the trachea and bronchi, the lungs, the thyroid, and the parathyroid.', 'Wikipedia: Germ layer', 'https://en.wikipedia.org/w/index.php?title=Germ_layer&oldid=1353509923', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'reproduction-development' and body = 'The endoderm is one of the germ layers formed during animal embryonic development. Cells migrate inward along the archenteron to form the inner layer of the gastrula, developing into the endoderm. The endoderm consists at first of flattened cells, which subsequently become columnar. It forms the epithelial lining of the whole of the digestive tract except part of the mouth and pharynx and the terminal part of the rectum (which are lined by involutions of the ectoderm). It also forms the lining cells of all the glands which open into the digestive tract, including those of the liver and pancreas; the epithelium of the auditory tube and tympanic cavity; the trachea, bronchi, and alveoli of the lungs; the bladder and part of the urethra; and the follicle lining of the thyroid gland and thymus. The endoderm forms the pharynx, the esophagus, the stomach, the small intestine, the colon, the liver, the pancreas, the bladder, the epithelial parts of the trachea and bronchi, the lungs, the thyroid, and the parathyroid.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'reproduction-development', 'Germ layer: Mesoderm', 'The mesoderm germ layer forms in the embryo of a triploblastic animal. During gastrulation, some of the cells migrating inward contribute to the mesoderm, an additional layer between the endoderm and the ectoderm. The formation of a mesoderm leads to the development of the coelom, the main body cavity. Organs formed inside a coelom can freely move, grow, and develop independently of the body wall while fluid cushions, protects them from shocks. The mesoderm has several components which develop into tissues: axial mesoderm, intermediate mesoderm, paraxial mesoderm, and lateral plate mesoderm. The axial mesoderm develops into the notochord. The intermediate mesoderm develops into kidneys and gonads. The paraxial mesoderm develops into cartilage, skeletal muscle, and dermis. The lateral plate mesoderm develops into the circulatory system (including the heart and spleen), the wall of the gut, and wall of the human body. Through cell signaling cascades and interactions with the ectodermal and endodermal cells, the mesodermal cells begin the process of differentiation. The mesoderm forms muscle tissue (smooth and striated), bone, cartilage, connective tissue, adipose tissue, circulatory system, lymphatic system, dermis, dentine of teeth, genitourinary system, serous membranes, spleen and notochord.', 'Wikipedia: Germ layer', 'https://en.wikipedia.org/w/index.php?title=Germ_layer&oldid=1353509923', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'reproduction-development' and body = 'The mesoderm germ layer forms in the embryo of a triploblastic animal. During gastrulation, some of the cells migrating inward contribute to the mesoderm, an additional layer between the endoderm and the ectoderm. The formation of a mesoderm leads to the development of the coelom, the main body cavity. Organs formed inside a coelom can freely move, grow, and develop independently of the body wall while fluid cushions, protects them from shocks. The mesoderm has several components which develop into tissues: axial mesoderm, intermediate mesoderm, paraxial mesoderm, and lateral plate mesoderm. The axial mesoderm develops into the notochord. The intermediate mesoderm develops into kidneys and gonads. The paraxial mesoderm develops into cartilage, skeletal muscle, and dermis. The lateral plate mesoderm develops into the circulatory system (including the heart and spleen), the wall of the gut, and wall of the human body. Through cell signaling cascades and interactions with the ectodermal and endodermal cells, the mesodermal cells begin the process of differentiation. The mesoderm forms muscle tissue (smooth and striated), bone, cartilage, connective tissue, adipose tissue, circulatory system, lymphatic system, dermis, dentine of teeth, genitourinary system, serous membranes, spleen and notochord.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'reproduction-development', 'Germ layer: Ectoderm', 'The ectoderm generates the outer layer of the embryo, and it forms from the embryo''s epiblast. The ectoderm develops into the surface ectoderm, neural crest, and the neural tube. The surface ectoderm develops into the epidermis, hair, nails, lens of the eye, sebaceous glands, cornea, tooth enamel, the epithelium of the mouth and nose. The neural crest of the ectoderm develops into the peripheral nervous system, adrenal medulla, melanocytes, and facial cartilage. The neural tube of the ectoderm develops into the brain, spinal cord, posterior pituitary, motor neurons, and retina. The anterior pituitary develops from the ectodermal tissue of Rathke''s pouch.', 'Wikipedia: Germ layer', 'https://en.wikipedia.org/w/index.php?title=Germ_layer&oldid=1353509923', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'reproduction-development' and body = 'The ectoderm generates the outer layer of the embryo, and it forms from the embryo''s epiblast. The ectoderm develops into the surface ectoderm, neural crest, and the neural tube. The surface ectoderm develops into the epidermis, hair, nails, lens of the eye, sebaceous glands, cornea, tooth enamel, the epithelium of the mouth and nose. The neural crest of the ectoderm develops into the peripheral nervous system, adrenal medulla, melanocytes, and facial cartilage. The neural tube of the ectoderm develops into the brain, spinal cord, posterior pituitary, motor neurons, and retina. The anterior pituitary develops from the ectodermal tissue of Rathke''s pouch.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'reproduction-development', 'Germ layer: Neural crest', 'Because of its great importance, the neural crest is sometimes considered a fourth germ layer. It is, however, derived from the ectoderm.', 'Wikipedia: Germ layer', 'https://en.wikipedia.org/w/index.php?title=Germ_layer&oldid=1353509923', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'reproduction-development' and body = 'Because of its great importance, the neural crest is sometimes considered a fourth germ layer. It is, however, derived from the ectoderm.');
